const cfg = $('Settings').first().json;
const camps = $('Active campaigns').all().map(i => i.json);
const rows = $input.all().map((item, i) => ({ name: camps[i]?.name || item.json.campaign_id, ...(item.json.totals || {}) }));
const pct = v => (v === null || v === undefined) ? '-' : `${Number(v).toFixed(1)}%`;
const tr = rows.map(r => `<tr><td>${r.name}</td><td>${r.sent ?? 0}</td><td>${r.replies ?? 0}</td><td>${pct(r.reply_rate)}</td><td>${r.positive ?? 0}</td><td>${pct(r.bounce_rate)}${Number(r.bounce_rate) > cfg.bounce_limit_pct ? ' (check)' : ''}</td></tr>`).join('');
const html = `<p>Last 7 days, ${rows.length} active campaign(s).</p><table border="1" cellpadding="4"><tr><th>Campaign</th><th>Sent</th><th>Replies</th><th>Reply rate</th><th>Positive</th><th>Bounce rate</th></tr>${tr}</table>`;
return [{ json: { to: cfg.report_to, html, campaigns: rows.length } }];
